import random

def get_value_at_index(index):
    id_sequence = [random.randint(1, 100000) for _ in range(1000)]
    if index < 0 or index >= len(id_sequence):
        return -1
    return id_sequence[index]

def main():
    try:
        index = int(input("Entrez un index : "))
        result = get_value_at_index(index)
        if result == -1:
            print("Index invalide (hors limites).")
        else:
            print(f"Valeur à l'index {index} : {result}")
    except ValueError:
        print("Veuillez entrer un entier valide.")

if __name__ == "__main__":
    main()

